CREATE TABLE IF NOT EXISTS `locations` (`id` int AUTO_INCREMENT NOT NULL, `shortCode` varchar(60) NOT NULL, `description` varchar(191) NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `locations_id` PRIMARY KEY(`id`), CONSTRAINT `locations_shortCode_unique` UNIQUE(`shortCode`));
CREATE TABLE IF NOT EXISTS `nodes` (`id` int AUTO_INCREMENT NOT NULL, `locationId` int NOT NULL, `name` varchar(100) NOT NULL, `description` varchar(191) NOT NULL, `fqdn` varchar(255) NOT NULL, `scheme` enum('http','https') NOT NULL DEFAULT 'https', `behindProxy` int NOT NULL DEFAULT 0, `public` int NOT NULL DEFAULT 1, `memoryMb` int NOT NULL, `diskMb` int NOT NULL, `memoryOverallocate` int NOT NULL DEFAULT 0, `diskOverallocate` int NOT NULL DEFAULT 0, `daemonPort` int NOT NULL DEFAULT 8080, `sftpPort` int NOT NULL DEFAULT 2022, `daemonToken` varchar(255) NOT NULL, `status` enum('offline','online','maintenance') NOT NULL DEFAULT 'offline', `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT `nodes_id` PRIMARY KEY(`id`), CONSTRAINT `nodes_fqdn_unique` UNIQUE(`fqdn`));
CREATE TABLE IF NOT EXISTS `allocations` (`id` int AUTO_INCREMENT NOT NULL, `nodeId` int NOT NULL, `ip` varchar(64) NOT NULL, `alias` varchar(255), `port` int NOT NULL, `serverId` int, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `allocations_id` PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `nests` (`id` int AUTO_INCREMENT NOT NULL, `name` varchar(100) NOT NULL, `description` text NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `nests_id` PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `eggs` (`id` int AUTO_INCREMENT NOT NULL, `nestId` int NOT NULL, `name` varchar(100) NOT NULL, `slug` varchar(100) NOT NULL, `image` varchar(255) NOT NULL, `startup` varchar(500) NOT NULL, `installScript` text NOT NULL, `environmentJson` text NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `eggs_id` PRIMARY KEY(`id`), CONSTRAINT `eggs_slug_unique` UNIQUE(`slug`));
CREATE TABLE IF NOT EXISTS `servers` (`id` int AUTO_INCREMENT NOT NULL, `ownerId` int NOT NULL, `nodeId` int NOT NULL, `allocationId` int, `eggId` int, `name` varchar(100) NOT NULL, `identifier` varchar(48) NOT NULL, `runtime` varchar(64) NOT NULL, `image` varchar(255) NOT NULL, `startup` varchar(500) NOT NULL, `memoryMb` int NOT NULL, `diskMb` int NOT NULL, `cpu` int NOT NULL, `status` enum('installing','offline','running','stopping','failed') NOT NULL DEFAULT 'offline', `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT `servers_id` PRIMARY KEY(`id`), CONSTRAINT `servers_identifier_unique` UNIQUE(`identifier`));
CREATE TABLE IF NOT EXISTS `schedules` (`id` int AUTO_INCREMENT NOT NULL, `serverId` int NOT NULL, `name` varchar(100) NOT NULL, `cron` varchar(100) NOT NULL, `action` enum('start','stop','restart','command') NOT NULL DEFAULT 'restart', `payload` text, `enabled` int NOT NULL DEFAULT 1, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `schedules_id` PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `backups` (`id` int AUTO_INCREMENT NOT NULL, `serverId` int NOT NULL, `name` varchar(100) NOT NULL, `archivePath` varchar(500) NOT NULL, `checksum` varchar(128), `bytes` int NOT NULL DEFAULT 0, `status` enum('pending','running','completed','failed') NOT NULL DEFAULT 'pending', `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `backups_id` PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `server_users` (`id` int AUTO_INCREMENT NOT NULL, `serverId` int NOT NULL, `userId` int NOT NULL, `permissionsJson` text NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `server_users_id` PRIMARY KEY(`id`));
ALTER TABLE `schedules` ADD COLUMN IF NOT EXISTS `lastRunAt` timestamp NULL;
CREATE TABLE IF NOT EXISTS `database_hosts` (`id` int AUTO_INCREMENT NOT NULL, `nodeId` int NOT NULL, `name` varchar(100) NOT NULL, `hostname` varchar(255) NOT NULL, `port` int NOT NULL, `username` varchar(100) NOT NULL, `password` varchar(255) NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `database_hosts_id` PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `server_databases` (`id` int AUTO_INCREMENT NOT NULL, `serverId` int NOT NULL, `hostId` int NOT NULL, `name` varchar(100) NOT NULL, `username` varchar(100) NOT NULL, `password` varchar(255) NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `server_databases_id` PRIMARY KEY(`id`));
